c = 200000
mod = 998244353
st = [0] * (4 * c)

def update(idx, ss, se, summ, num):
	if ss == se and ss == num:
		st[idx] = (st[idx] + summ) % mod
		return
	mid = (ss + se) // 2
	if mid >= num:
		update(2 * idx + 1, ss, mid, summ, num)
	else:
		update(2 * idx + 2, mid + 1, se, summ, num)
	st[idx] = (st[idx * 2 + 1] + st[idx * 2 + 2]) % mod

def rangesum(idx, ss, se, rs, re):
	if rs <= ss and se <= re:
		return st[idx]
	elif re < ss or se < rs:
		return 0
	else:
		mid = (ss + se) // 2
		return (rangesum(2 * idx + 1, ss, mid, rs, re) + rangesum(2 * idx + 2, mid + 1, se, rs, re)) % mod
n = int(input())
s = list(map(int, input().split()))
for i in range(n):
	count = 1
	if s[i] != 1:
		count = (1 + rangesum(0, 1, 200000, 1, s[i] - 1)) % mod
	update(0, 1, 200000, count, s[i])
